<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/functions.php';
$user = require_login($pdo);
$id = (int)($_GET['id'] ?? 0);
$stmt = $pdo->prepare('SELECT i.*, u.full_name AS poster_name FROM items i JOIN users u ON u.id=i.created_by WHERE i.id=? LIMIT 1'); $stmt->execute([$id]); $item = $stmt->fetch();
if (!$item) { http_response_code(404); render_header('Item not found'); echo '<div class="panel"><div class="empty-state"><div class="empty-icon">?</div><strong>Item not found</strong><p>This record may have been removed or the link is incorrect.</p><a href="lost-items.php" class="btn btn-primary">Back to items</a></div></div>'; render_footer(); exit; }
if ($user['role'] === 'student' && $item['item_type'] === 'lost' && $item['status'] === 'closed') { http_response_code(404); set_flash('info','This lost report is closed.'); redirect('lost-items.php'); }
render_header('Item details', $item['item_type']);
?>
<div class="page-header"><div><div class="eyebrow"><span class="pulse-dot"></span> ITEM REFERENCE · <?= e($item['reference_code']) ?></div><h1>Item details</h1><p>Review the record and follow the school instructions below.</p></div><a class="btn btn-outline" href="<?= $item['item_type']==='lost'?'lost-items.php':'found-items.php' ?>">← Back to <?= e(ucfirst($item['item_type'])) ?> Items</a></div>
<div class="item-detail-grid"><div class="item-detail-image"><?php if ($item['image_path']): ?><img src="<?= e(private_image_url('item',(int)$item['id'])) ?>" alt="Photo of <?= e($item['title']) ?>"><?php else: ?><span class="item-placeholder"><?= $item['item_type']==='lost'?'⌕':'◇' ?></span><?php endif; ?></div><section class="panel details-card"><div class="action-row"><span class="pill"><?= e(ucfirst($item['item_type'])) ?> record</span><span class="status-badge status-<?= e(status_class($item['status'])) ?>"><?= e(status_label($item['status'])) ?></span></div><h1><?= e($item['title']) ?></h1><p class="detail-description"><?= nl2br(e($item['description'])) ?></p><div class="detail-row"><span>Reference number</span><strong><?= e($item['reference_code']) ?></strong></div><div class="detail-row"><span>Category</span><strong><?= e($item['category']) ?></strong></div><div class="detail-row"><span>Location</span><strong><?= e($item['location_found_or_lost']) ?></strong></div><div class="detail-row"><span>Date <?= $item['item_type']==='lost'?'reported lost':'found' ?></span><strong><?= e(date('F j, Y',strtotime($item['event_date']))) ?></strong></div><div class="detail-row"><span>Record posted</span><strong><?= e(date('M j, Y',strtotime($item['created_at']))) ?></strong></div>
<?php if ($item['item_type'] === 'found'): ?><div class="claim-note"><strong>How to claim this item</strong><br>If this item belongs to you, visit the <strong><?= e(OFFICE_LOCATION) ?></strong> in person and provide reference <strong><?= e($item['reference_code']) ?></strong>. School staff will ask you to describe the item and verify ownership before releasing it. Do not share private proof of ownership in public comments.<?php if ($item['status']==='returned'): ?><br><br><strong>This item has already been returned.</strong><?php elseif ($item['status']!=='available_for_claim'): ?><br><br><strong>This item is not currently marked as available for claim.</strong><?php endif; ?></div><?php else: ?><div class="claim-note"><strong>About this lost report</strong><br>If you have information about this item, contact the school Admin/Teacher and provide reference <strong><?= e($item['reference_code']) ?></strong>. The school team will update the report after checking the information.</div><?php endif; ?>
</section></div>
<?php render_footer(); ?>
